import{_ as i,a0 as s,w as p,s as d,ao as n,I as o,x as t,a1 as a,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"4 款值得一試的 Linux 終端多路複用器 | LCTT x X-CMD","titleTemplate":false,"description":"4 款值得一試的 Linux 終端多路複用器 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"4 款值得一試的 Linux 終端多路複用器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"4 款值得一試的 Linux 終端多路複用器 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210512 4 Linux terminal multiplexers to try","title":"4 款值得一試的 Linux 終端多路複用器","tag":"202105","desc":""},"relativePath":"202105/20210512 4 Linux terminal multiplexers to try.md","filePath":"[post].md"}'),m={name:"202105/20210512 4 Linux terminal multiplexers to try.md"};function u(x,e,h,f,T,b){const r=s("Link");return p(),d("div",null,[e[28]||(e[28]=n('<h1 id="_4-款值得一試的-linux-終端多路複用器" tabindex="-1">4 款值得一試的 Linux 終端多路複用器 <a class="header-anchor" href="#_4-款值得一試的-linux-終端多路複用器" aria-label="Permalink to “4 款值得一試的 Linux 終端多路複用器”">​</a></h1><blockquote><p>比較 tmux、GNU Screen、Konsole 和 Terminator，看看哪個最適合你。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202105/24/205044ez55fdw99alhhgn8.jpg" alt=""></p><p>Linux 用户通常需要大量的虛擬視覺空間。一個終端窗口是永遠不夠的，所以終端有了標籤。一個桌面太受限制了，所以有了虛擬桌面。當然，應用程序窗口可以堆疊，但當它們堆疊起來時，又有多大的好處呢？哎呀，即使是後台文本控制台也有 <code>F1</code> 到 <code>F7</code>，可以在任務之間來回翻轉。</p><p>有了這麼多的多任務處理方式，有人發明了終端 <em>多路複用器</em> 的概念就不奇怪了。誠然，這是一個令人困惑的術語。在傳統的電子學中，“<ruby>多路複用器<rt>multiplexer</rt></ruby>”是一個接收多個輸入信號並將選定的信號轉發到單一輸出的部件。終端多路複用器的作用正好相反。它從一個輸入（人類在鍵盤上向一個終端窗口打字）接收指令，並將該輸入轉發給任意數量的輸出（例如，一組服務器）。</p><p>然後，“多路複用器”一詞在美國也是一個流行的術語，指的是有許多屏幕的電影院（與“<ruby>影城<rt>cineplex</rt></ruby>”一詞一個意思）。在某種程度上，這很好地描述了終端複用器的作用。它可以在一個框內提供許多屏幕。</p><p>不管這個詞是什麼意思，任何嘗試過它的人都有自己的喜好的某一種多路複用器。因此，我決定考察一些流行的終端多路複用器，看看每一個都怎麼樣。就我的評估標準而言，最低限度，我需要每個多路複用器能夠分割<em>和</em>堆疊終端窗口。</p><h3 id="tmux" tabindex="-1">tmux <a class="header-anchor" href="#tmux" aria-label="Permalink to “tmux”">​</a></h3><p><img src="https://opensource.com/sites/default/files/uploads/multiplex-tmux.png" alt="tmux" title="tmux"></p><p>據我所知，是從 tmux 開始使用“多路複用器”這個術語的。它工作的很出色。</p><p>它作為一個守護程序運行，這樣即使你關閉了正在查看的終端模擬器，你的終端會話仍然處於活動狀態。它將你的終端屏幕分割成多個面板，這樣你就可以在每個面板上打開獨特的終端提示符。</p><p>推而廣之，這意味着你也可以遠程連接到任何數量的系統，並在你的終端中打開它們。利用 tmux 的能力，將輸入鏡像（或者以電子學術語説是“反向多路複用”）到其他打開的窗格，就能從一箇中央命令窗格同時控制幾台計算機。</p><p>tmux 在 GNU Screen 還只能水平分割的時候就有了垂直分割能力，這吸引了追求最大靈活性的粉絲。而靈活性正是用户在 tmux 中得到的。它可以分割、堆疊、選擇和提供服務；幾乎沒有什麼是它做不到的。</p><h4 id="📦-軟件包大小" tabindex="-1">📦 軟件包大小 <a class="header-anchor" href="#📦-軟件包大小" aria-label="Permalink to “📦 軟件包大小”">​</a></h4><p>從軟件包中安裝 tmux 大約需要 700K，這還不算它所依賴的十幾個共享庫。</p><h4 id="🎛️-控制鍵" tabindex="-1">🎛️ 控制鍵 <a class="header-anchor" href="#🎛️-控制鍵" aria-label="Permalink to “🎛️ 控制鍵”">​</a></h4><p>tmux 的默認觸發鍵是 <code>Ctrl+B</code>，儘管很容易在其配置文件中重新定義。</p><h4 id="⌨️-黑客因子" tabindex="-1">⌨️ 黑客因子 <a class="header-anchor" href="#⌨️-黑客因子" aria-label="Permalink to “⌨️ 黑客因子”">​</a></h4><p>即使你只是在學習如何使用終端，你也一定會覺得使用 tmux 的人很像黑客。它看起來很複雜，但一旦你瞭解了正確的鍵綁定，就很容易使用。它為你提供了很多有用的技巧，讓你玩的飛起，而且它是一種快速構建 HUD（抬頭顯示器）的超簡單方法，可以把你需要的所有信息擺在你面前。</p><h3 id="gnu-screen" tabindex="-1">GNU Screen <a class="header-anchor" href="#gnu-screen" aria-label="Permalink to “GNU Screen”">​</a></h3><p><img src="https://opensource.com/sites/default/files/uploads/multiplex-screen.png" alt="GNU Screen" title="GNU Screen"></p><p>像 tmux 一樣，GNU Screen 也運行一個守護程序，所以即使你關閉了用來啓動它的終端，你的 shell 仍然可用。你可以從不同的計算機上連接並共享屏幕。它可以將你的終端屏幕分割成水平或垂直的窗格。</p><p>與 tmux 不同的是，GNU Screen 可以通過串行連接進行連接（<code>screen 9600 /dev/ttyUSB0</code> 就可以了），通過按鍵綁定可以方便地發出 <code>XON</code> 和 <code>XOFF</code> 信號。</p>',23)),o("p",null,[e[1]||(e[1]=t("與 SSH 會話相比，在串行連接中需要多路複用器的情況可能並不常見，所以大多數用户並不瞭解 Screen 這個真正特殊的功能。不過，GNU Screen 是一個很棒的多路複用器，有很多有用的選項。而如果你真的需要同時向多個服務器發送信號，還有專門的工具，比如 ClusterSSH 和 ",-1)),a(r,{href:"https://opensource.com/article/19/2/quickstart-guide-ansible"},{default:l(()=>[...e[0]||(e[0]=[t("Ansible",-1)])]),_:1}),e[2]||(e[2]=t("。",-1))]),e[29]||(e[29]=n('<h4 id="📦-軟件包大小-1" tabindex="-1">📦 軟件包大小 <a class="header-anchor" href="#📦-軟件包大小-1" aria-label="Permalink to “📦 軟件包大小”">​</a></h4><p>從軟件包中安裝 GNU Screen 大約需要 970K，這還不算它所依賴的十幾個共享庫。</p><h4 id="🎛️-控制鍵-1" tabindex="-1">🎛️ 控制鍵 <a class="header-anchor" href="#🎛️-控制鍵-1" aria-label="Permalink to “🎛️ 控制鍵”">​</a></h4><p>GNU Screen 的默認觸發鍵是 <code>Ctrl+A</code>，這對於熟悉 Bash 快捷鍵的人來説可能特別煩人。幸運的是，你可以在配置文件中輕鬆地重新定義這個觸發鍵。</p><h4 id="⌨️-黑客因子-1" tabindex="-1">⌨️ 黑客因子 <a class="header-anchor" href="#⌨️-黑客因子-1" aria-label="Permalink to “⌨️ 黑客因子”">​</a></h4><p>當使用 Screen 通過串行連接到你的路由器或你的原型電路板時，你會成為你所有硬件黑客朋友羨慕的對象。</p><h3 id="konsole" tabindex="-1">Konsole <a class="header-anchor" href="#konsole" aria-label="Permalink to “Konsole”">​</a></h3><p><img src="https://opensource.com/sites/default/files/uploads/multiplex-konsole.png" alt="Konsole" title="Konsole"></p><p>對於沒有標榜自己是多路複用器的 Konsole 來説，令人驚訝的是它也是其中一個。它可以使用 Qt 窗格和標籤進行必要的窗口分割和堆疊，但它也可以通過“編輯（將輸入複製到）”菜單中的一個選項將輸入從一個窗格傳到另一個（或全部）。</p>',9)),o("p",null,[e[5]||(e[5]=t("然而，它所最明顯缺乏的功能是作為一個守護程序運行以進行遠程重新連接的能力。與 tmux 和 GNU Screen 不同，你不能遠程連接到運行 Konsole 的機器並加入會話。對於一些管理員來説，這可能不是一個問題。許多管理員用 ",-1)),a(r,{href:"https://en.wikipedia.org/wiki/Virtual_Network_Computing"},{default:l(()=>[...e[3]||(e[3]=[t("VNC",-1)])]),_:1}),e[6]||(e[6]=t(" 連接到機器的次數比用 ",-1)),a(r,{href:"https://en.wikipedia.org/wiki/Secure_Shell_Protocol"},{default:l(()=>[...e[4]||(e[4]=[t("SSH",-1)])]),_:1}),e[7]||(e[7]=t(" 還要多，所以“重新加入”一個會話就像在 VNC 客户端上點擊 Konsole 窗口一樣簡單。",-1))]),o("p",null,[e[9]||(e[9]=t("使用 Konsole 作為多路複用器是 KDE 極客們的大招。Konsole 是我使用的第一個 Linux 終端（直到今天，我有時也會按 ",-1)),e[10]||(e[10]=o("code",null,"Ctrl+N",-1)),e[11]||(e[11]=t(" 來切換新標籤），所以有能力使用這個熟悉的終端作為多路複用器是一個很大的便利。這絕不是必要的，因為無論如何 tmux 和 Screen 都可以在 Konsole 裏面運行，但是通過讓 Konsole 處理窗格，我就不必調整肌肉記憶。這種微妙的功能包容正是 ",-1)),a(r,{href:"https://opensource.com/article/19/12/linux-kde-plasma"},{default:l(()=>[...e[8]||(e[8]=[t("KDE 的偉大之處",-1)])]),_:1}),e[12]||(e[12]=t("。",-1))]),e[30]||(e[30]=n('<h4 id="📦-軟件包大小-2" tabindex="-1">📦 軟件包大小 <a class="header-anchor" href="#📦-軟件包大小-2" aria-label="Permalink to “📦 軟件包大小”">​</a></h4><p>Konsole 本身大約是 11KB，但它依賴於 105 個 KDE 和 Qt 庫，所以實際上，它至少有 50MB。</p><h4 id="🎛️-控制鍵-2" tabindex="-1">🎛️ 控制鍵 <a class="header-anchor" href="#🎛️-控制鍵-2" aria-label="Permalink to “🎛️ 控制鍵”">​</a></h4><p>大多數重要的 Konsole 快捷鍵以 <code>Shift+Ctrl</code> 開始，分割屏幕、打開新標籤、複製輸入到其他窗格等都是如此。這是 KDE 裏的主控台，所以如果你對 Plasma 桌面很熟悉，會感覺快捷鍵很熟悉。</p><h4 id="⌨️-黑客因子-2" tabindex="-1">⌨️ 黑客因子 <a class="header-anchor" href="#⌨️-黑客因子-2" aria-label="Permalink to “⌨️ 黑客因子”">​</a></h4><p>使用 Konsole 作為你的多路複用器讓你有資格稱自己為 KDE 高級用户。</p><h3 id="terminator" tabindex="-1">Terminator <a class="header-anchor" href="#terminator" aria-label="Permalink to “Terminator”">​</a></h3><p><img src="https://opensource.com/sites/default/files/uploads/multiplex-terminator.png" alt="Terminator" title="Terminator"></p><p>對於 GNOME 用户來説，Terminator 多路複用器是為他們原本極簡的 GNOME 終端增加功能的一個簡單方法。除了必要的多路複用功能外，Terminator 還可以向所有打開的窗格廣播輸入，但和 Konsole 一樣，它不會在後台運行以便你可以通過 SSH 重新連接到它。話説回來，由於 GNOME 和 Wayland 讓 VNC 變得如此簡單，你有可能會覺得沒有必要通過 SSH 來恢復終端會話。</p><p>如果你願意，Terminator 可以完全由鼠標驅動。Konsole 通過其主菜單也有同樣的能力。有了 Terminator，你可以在 Shell 的任何地方點擊右鍵，彈出相關選項，以水平或垂直分割窗口，將窗格分組作為廣播目標，廣播輸入，關閉窗格，等等。你還可以為所有這些動作配置鍵盤快捷鍵，所以在許多方面，你可以形成自己的體驗。</p><p>我認為自己主要是一個 KDE 用户，所以當我説 Terminator 感覺像一個 KDE 應用時，我其實是一種極大的讚美。Terminator 是一個令人驚訝的可配置的和靈活的應用程序。在許多方面，它體現了開源的力量，把簡陋的 GNOME 終端變成了一個強大的多路複用器。</p><h4 id="📦-軟件包大小-3" tabindex="-1">📦 軟件包大小 <a class="header-anchor" href="#📦-軟件包大小-3" aria-label="Permalink to “📦 軟件包大小”">​</a></h4><p>Terminator 的安裝容量為 2.2MB，其中大部分是 Python 模組。但它依賴於 GTK3 和 GNOME，所以如果你沒有運行完整的 GNOME 桌面，可以預料你需要一個更大的安裝來拉入這些依賴。</p><h4 id="🎛️-控制鍵-3" tabindex="-1">🎛️ 控制鍵 <a class="header-anchor" href="#🎛️-控制鍵-3" aria-label="Permalink to “🎛️ 控制鍵”">​</a></h4><p>Terminator 的默認控制鍵沒有什麼一致性。你可以用 <code>Alt</code> 鍵來執行一些命令，用 <code>Ctrl</code> 來執行其他命令，還可以用 <code>Shift+Ctrl</code>、<code>Ctrl+Alt</code>、<code>Shift+Super</code> 等等，還有鼠標。話説回來，這是我試過的最可配置的多路複用器之一，所以只要有想法，稍加努力，你就能設計出適合你的模式。</p><h4 id="⌨️-黑客因子-3" tabindex="-1">⌨️ 黑客因子 <a class="header-anchor" href="#⌨️-黑客因子-3" aria-label="Permalink to “⌨️ 黑客因子”">​</a></h4><p>當你使用 Terminator 時，你會覺得自己是最現代、最務實的黑客。由於它的各種極客選項，它是多路複用的最佳選擇，而且由於它非常靈活，無論你的手是在鍵盤上，還是鍵盤和鼠標並用，你都可以同樣輕鬆地使用它。</p><h3 id="我全要" tabindex="-1">我全要 <a class="header-anchor" href="#我全要" aria-label="Permalink to “我全要”">​</a></h3><p>還有更多的多路複用器和一些具有類似多路複用能力的應用。你不必非要找到<em>一個</em>完全按照你想要的方式完成你需要的所有工作的多路複用器。你可以使用不止一個。事實上，你甚至可以同時使用多個，因為 tmux 和 Screen 實際上是 shell，而 Konsole 和 Terminator 是顯示 shell 的終端。對唾手可得的工具感到舒適，而且它們能幫助你管理你的工作空間，使你能有效地工作，才是最重要的。</p><p>去嘗試一下多路複用器，或者在你喜歡的應用程序中發現類似多路複用器的功能。它可能會改變你看待計算的方式。</p><hr>',21)),o("p",null,[e[14]||(e[14]=t("via: ",-1)),a(r,{href:"https://opensource.com/article/21/5/linux-terminal-multiplexer"},{default:l(()=>[...e[13]||(e[13]=[t("https://opensource.com/article/21/5/linux-terminal-multiplexer",-1)])]),_:1})]),o("p",null,[e[19]||(e[19]=t("作者：",-1)),a(r,{href:"https://opensource.com/users/seth"},{default:l(()=>[...e[15]||(e[15]=[t("Seth Kenlon",-1)])]),_:1}),e[20]||(e[20]=t(" 選題：",-1)),a(r,{href:"https://github.com/lujun9972"},{default:l(()=>[...e[16]||(e[16]=[t("lujun9972",-1)])]),_:1}),e[21]||(e[21]=t(" 譯者：",-1)),a(r,{href:"https://github.com/wxy"},{default:l(()=>[...e[17]||(e[17]=[t("wxy",-1)])]),_:1}),e[22]||(e[22]=t(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:l(()=>[...e[18]||(e[18]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[25]||(e[25]=t("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[23]||(e[23]=[t("LCTT",-1)])]),_:1}),e[26]||(e[26]=t(" 原創編譯，",-1)),a(r,{href:"https://linux.cn/"},{default:l(()=>[...e[24]||(e[24]=[t("Linux中國",-1)])]),_:1}),e[27]||(e[27]=t(" 榮譽推出",-1))])])}const N=i(m,[["render",u]]);export{C as __pageData,N as default};
